"""The pack catalogue (packs/catalogue.json, generated by scripts/packs.py) joined with what this OmniGate actually has loaded."""
import json, os
PATH = os.environ.get("PACKS_CATALOGUE", os.path.join(os.path.dirname(os.path.abspath(__file__)), "..", "..", "packs", "catalogue.json"))

def load(path=None):
    with open(path or PATH) as f: return json.load(f)["packs"]

def with_loaded(packs, workspace_ids, starter_pack_ids):
    """loaded: 'workspace' (a Workspace named for the pack exists), 'category' (the Ask picker lists it), or None (unknown: a single-pack stack reports neither).
    The reason is always given, so a disabled card can say why."""
    out = []
    for p in packs:
        if p["id"] in workspace_ids: state, why = "workspace", "A Workspace named %s exists." % p["id"]
        elif p["id"] in starter_pack_ids: state, why = "category", "Approved questions are loaded for it, but no Workspace is configured for it."
        else: state, why = None, "Not reported by this OmniGate (a single-pack stack does not list its pack, and no Workspace is configured)."
        out.append(dict(p, loaded=state, loadedReason=why))
    return out
